<?php
declare(strict_types=1);
function render_route(string $path): void {
 if($path!=='/'&&str_ends_with($path,'/')){
  $clean=rtrim($path,'/');
  if(preg_match('#^/(?:products(?:/[a-z0-9-]+)?|categories/[0-9]+-[a-z0-9-]+|about|contact|faq|wholesale)$#',$clean)){
   $query=parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_QUERY);
   redirect(url($clean).($query!==null&&$query!==false?'?'.$query:''),301);
  }
  $path=$clean;
 }
 if(str_starts_with($path,'/categories/')&&category_page($path))return;
 if($path==='/robots.txt'){header('Content-Type: text/plain; charset=utf-8');echo "User-agent: *\nAllow: /\nDisallow: /install\nSitemap: ".url('/sitemap.xml');return;}
 if($path==='/sitemap.xml'){require_once __DIR__.'/sitemap.php';serve_sitemap();return;}
 if($path==='/admin'){if((current_user()['role']??'')!=='ADMIN')redirect('/login');require __DIR__.'/admin.php';render_admin();return;}
 if($path==='/'){home_page();return;}
 if($path==='/products'){catalog_page();return;}
 if(preg_match('#^/products/([a-z0-9-]+)$#',$path,$m)){detail_page($m[1]);return;}
 if(in_array($path,['/cart','/checkout'],true)){cart_page($path==='/checkout');return;}
 if(in_array($path,['/login','/register','/wholesale'],true)){auth_page($path!=='/login',$path==='/wholesale');return;}
 if($path==='/forgot-password'){page_header('بازیابی رمز عبور','',false);echo '<div class="container page-content"><div class="panel auth-form"><h1>بازیابی رمز با پیامک</h1><p>ارسال پیامک هنوز توسط مدیر فروشگاه پیکربندی نشده است. برای بازیابی حساب با پشتیبانی تماس بگیرید.</p><a class="btn" href="/contact">تماس با پشتیبانی</a><a class="text-link" href="/login">بازگشت به ورود</a></div></div>';page_footer();return;}
 if($path==='/account'){account_page();return;}
 if($path==='/track'){track_page();return;}
 if(in_array($path,['/about','/contact','/faq'],true)){info_page($path);return;}
 http_response_code(404);page_header('صفحه پیدا نشد','',false);echo '<div class="empty-state"><h1>صفحه پیدا نشد</h1><a class="btn" href="/">بازگشت به فروشگاه</a></div>';page_footer();
}
